// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.automation.schedulerimport android.app.PendingIntentimport android.content.BroadcastReceiverimport android.content.Contextimport android.content.Intentimport android.content.IntentFilterimport android.os.Buildimport androidx.work.BackoffPolicyimport androidx.work.ExistingPeriodicWorkPolicyimport androidx.work.ExistingWorkPolicyimport androidx.work.OneTimeWorkRequestimport androidx.work.OneTimeWorkRequestBuilderimport androidx.work.PeriodicWorkRequestimport androidx.work.PeriodicWorkRequestBuilderimport androidx.work.WorkManagerimport androidx.work.workDataOfimport com.google.android.gms.location.Geofenceimport com.google.android.gms.location.GeofencingClientimport com.google.android.gms.location.GeofencingRequestimport com.google.android.gms.location.LocationServicesimport com.roshan.persona.automation.engine.AutomationEngineimport com.roshan.persona.automation.model.AutomationRuleimport com.roshan.persona.automation.model.AutomationTriggerimport com.roshan.persona.automation.model.EventTypeimport com.roshan.persona.automation.model.LocationActionimport com.roshan.persona.automation.model.StateTypeimport com.roshan.persona.automation.parser.AutomationNlParserimport com.roshan.persona.automation.worker.AutomationEventReceiverimport com.roshan.persona.automation.worker.AutomationGeofenceReceiverimport com.roshan.persona.automation.worker.AutomationWorkerimport timber.log.Timberimport java.util.concurrent.ConcurrentHashMapimport java.util.concurrent.TimeUnitimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Automation Scheduler (Module 8). * * Schedules triggers via the appropriate Android primitive: * *   - [AutomationTrigger.TimeTrigger]      → WorkManager `PeriodicWorkRequest` *                                            (24h interval, initial delay = ms *                                            until next fire). The worker *                                            checks `daysOfWeek` before firing. *   - [AutomationTrigger.LocationTrigger]  → `GeofencingClient` (Google Play *                                            Services Location). Transitions *                                            are received by *                                            [AutomationGeofenceReceiver]. *   - [AutomationTrigger.EventTrigger]     → Dynamic `BroadcastReceiver` *                                            (registered via `Context.registerReceiver`) *                                            for the matching system action. *   - [AutomationTrigger.StateTrigger]     → Dynamic `BroadcastReceiver` *                                            for the state-change broadcast. *   - [AutomationTrigger.CompoundTrigger]  → Each child trigger is scheduled *                                            individually; the parent is *                                            evaluated by [AutomationEngine] *                                            when any child fires. * * All scheduling is idempotent — calling [schedule] for an already-scheduled * rule replaces the previous schedule (WorkManager `ExistingWorkPolicy.REPLACE`, * GeofencingClient `removeGeofences` + `addGeofences`). * * @see <a href="docs/strategy/NOUS-Strategy-2-14-extracted.txt">§2.2 Automation</a> */@Singletonclass AutomationScheduler @Inject constructor(    @dagger.hilt.android.qualifiers.ApplicationContext private val context: Context,) {    companion object {        private const val TAG = "NOUS.Auto.Scheduler"        /** WorkManager unique-work prefix for time-triggered rules. */        const val TIME_WORK_PREFIX = "automation_time_"        /** WorkManager unique-work prefix for one-shot fire rules. */        const val FIRE_WORK_PREFIX = "automation_fire_"        /** WorkManager tag for all automation work (used by cancelAll). */        const val AUTOMATION_WORK_TAG = "nous_automation"        /** Geofence pending-intent request-code base. */        const val GEOFENCE_PI_BASE = 0xA000        /** Minimum periodic-work interval (WorkManager enforces 15 min). */        const val MIN_PERIODIC_INTERVAL_MIN = 15L    }    /** Lazily-initialized WorkManager singleton. */    private val workManager: WorkManager by lazy { WorkManager.getInstance(context) }    /** Lazily-initialized GeofencingClient (Play Services Location). */    private val geofencingClient: GeofencingClient by lazy {        LocationServices.getGeofencingClient(context)    }    /**     * Active dynamic receivers, keyed by rule ID.     *     * Each [EventTrigger] / [StateTrigger] rule gets one BroadcastReceiver     * registered for its specific action. We track them here so [cancel]     * can unregister them.     */    private val activeReceivers = ConcurrentHashMap<String, BroadcastReceiver>()    /**     * Geofence rule IDs currently registered with the GeofencingClient.     * Used by [cancelAll] to bulk-remove.     */    private val activeGeofenceIds = ConcurrentHashMap.newKeySet<String>()    // ═══════════════════════════════════════════════════════════════════════════    // Schedule (dispatch by trigger type)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Schedule the rule's trigger. Dispatches by [AutomationTrigger] type.     *     * Idempotent — calling [schedule] for an already-scheduled rule replaces     * the previous schedule.     */    fun schedule(rule: AutomationRule) {        if (!rule.isEnabled) {            Timber.tag(TAG).d("schedule: rule '%s' is disabled — skipping", rule.name)            return        }        try {            when (val trigger = rule.trigger) {                is AutomationTrigger.TimeTrigger -> scheduleTimeTrigger(rule, trigger)                is AutomationTrigger.LocationTrigger -> scheduleLocationTrigger(rule, trigger)                is AutomationTrigger.EventTrigger -> scheduleEventTrigger(rule, trigger)                is AutomationTrigger.StateTrigger -> scheduleStateTrigger(rule, trigger)                is AutomationTrigger.CompoundTrigger -> scheduleCompoundTrigger(rule, trigger)            }        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "Failed to schedule rule '%s' (id=%s)", rule.name, rule.id)        }    }    /**     * Cancel all scheduled work for a rule (WorkManager + geofence + receiver).     */    fun cancel(ruleId: String) {        // WorkManager — cancel by unique-work name + tag.        workManager.cancelUniqueWork("$TIME_WORK_PREFIX$ruleId")        workManager.cancelUniqueWork("$FIRE_WORK_PREFIX$ruleId")        workManager.cancelAllWorkByTag(ruleId)        // Geofence — remove by request ID.        if (activeGeofenceIds.remove(ruleId)) {            try {                geofencingClient.removeGeofences(listOf(ruleId))                    .addOnSuccessListener {                        Timber.tag(TAG).d("Geofence removed for rule %s", ruleId)                    }                    .addOnFailureListener { e ->                        Timber.tag(TAG).w(e, "Failed to remove geofence for rule %s", ruleId)                    }            } catch (t: Throwable) {                Timber.tag(TAG).w(t, "Geofence removal threw for rule %s", ruleId)            }        }        // Dynamic receiver — unregister.        activeReceivers.remove(ruleId)?.let { receiver ->            try {                context.unregisterReceiver(receiver)                Timber.tag(TAG).d("Unregistered receiver for rule %s", ruleId)            } catch (t: Throwable) {                // Receiver wasn't registered (or already unregistered) — fine.                Timber.tag(TAG).d("Receiver unregister skipped for %s: %s", ruleId, t.message)            }        }    }    /**     * Cancel ALL scheduled automation work (WorkManager + geofences + receivers).     *     * Used by [AutomationEngine] for shutdown + tests.     */    fun cancelAll() {        // WorkManager — cancel all automation-tagged work.        workManager.cancelAllWorkByTag(AUTOMATION_WORK_TAG)        // Geofences — remove all.        if (activeGeofenceIds.isNotEmpty()) {            val ids = activeGeofenceIds.toList()            activeGeofenceIds.clear()            try {                geofencingClient.removeGeofences(ids)            } catch (t: Throwable) {                Timber.tag(TAG).w(t, "Bulk geofence removal failed")            }        }        // Receivers — unregister all.        for ((ruleId, receiver) in activeReceivers) {            try {                context.unregisterReceiver(receiver)            } catch (t: Throwable) {                Timber.tag(TAG).d("Receiver unregister skipped for %s: %s", ruleId, t.message)            }        }        activeReceivers.clear()    }    // ═══════════════════════════════════════════════════════════════════════════    // Per-trigger scheduling    // ═══════════════════════════════════════════════════════════════════════════    /**     * Schedule a [AutomationTrigger.TimeTrigger] via WorkManager PeriodicWorkRequest.     *     * The work repeats every 24h with an initial delay calculated to land at     * the next `[hour]:[minute]` local time. The worker checks `daysOfWeek`     * before firing — if today is not a firing day, the worker returns     * `Result.success()` without firing the action.     */    private fun scheduleTimeTrigger(        rule: AutomationRule,        trigger: AutomationTrigger.TimeTrigger,    ) {        val delayMs = AutomationNlParser.nextFireDelayMs(trigger)        // PeriodicWorkRequest minimum interval is 15 min; we use 24h since        // most time triggers are daily. The worker re-checks the next-fire        // time + day-of-week filter on every invocation.        val request: PeriodicWorkRequest = PeriodicWorkRequestBuilder<AutomationWorker>(            24, TimeUnit.HOURS,        )            .setInitialDelay(delayMs, TimeUnit.MILLISECONDS)            .setBackoffCriteria(BackoffPolicy.LINEAR, 60_000L, TimeUnit.MILLISECONDS)            .addTag(AUTOMATION_WORK_TAG)            .addTag(rule.id)            .setInputData(                workDataOf(                    AutomationWorker.KEY_RULE_ID to rule.id,                    AutomationWorker.KEY_TRIGGER_KIND to AutomationWorker.TRIGGER_KIND_TIME,                ),            )            .build()        workManager.enqueueUniquePeriodicWork(            "$TIME_WORK_PREFIX${rule.id}",            ExistingPeriodicWorkPolicy.UPDATE,            request,        )        Timber.tag(TAG).i(            "Scheduled TimeTrigger for '%s' (id=%s, delay=%dms, hour=%d:%02d)",            rule.name, rule.id, delayMs, trigger.hour, trigger.minute,        )    }    /**     * Schedule a [AutomationTrigger.LocationTrigger] via GeofencingClient.     *     * Adds a never-expiring geofence with the specified transition type.     * Transitions are received by [AutomationGeofenceReceiver], which     * forwards them to [AutomationWorker] via a OneTimeWorkRequest.     */    private fun scheduleLocationTrigger(        rule: AutomationRule,        trigger: AutomationTrigger.LocationTrigger,    ) {        // Check Google Play Services availability — on Huawei devices without GMS,        // LocationServices.getGeofencingClient() returns a client that throws        // on first use. We detect + log + return early.        val gmsAvailable = com.google.android.gms.common.GoogleApiAvailability.getInstance()            .isGooglePlayServicesAvailable(context) == com.google.android.gms.common.ConnectionResult.SUCCESS        if (!gmsAvailable) {            Timber.tag(TAG).w(                "Google Play Services not available — geofence for rule '%s' (id=%s) cannot be scheduled. " +                    "Location-based automations require GMS.",                rule.name, rule.id,            )            return        }        val transitionType = when (trigger.action) {            LocationAction.ENTER -> Geofence.GEOFENCE_TRANSITION_ENTER            LocationAction.EXIT -> Geofence.GEOFENCE_TRANSITION_EXIT            LocationAction.DWELL -> Geofence.GEOFENCE_TRANSITION_DWELL        }        val geofence = Geofence.Builder()            .setRequestId(rule.id)            .setCircularRegion(trigger.latitude, trigger.longitude, trigger.radiusMeters)            .setExpirationDuration(Geofence.NEVER_EXPIRE)            .setTransitionTypes(transitionType)            .setNotificationResponsiveness(5 * 60 * 1000)  // 5 min            .build()        val request = GeofencingRequest.Builder()            .setInitialTrigger(                if (trigger.action == LocationAction.ENTER) {                    GeofencingRequest.INITIAL_TRIGGER_ENTER                } else {                    0  // no initial trigger for EXIT / DWELL                },            )            .addGeofence(geofence)            .build()        val intent = Intent(context, AutomationGeofenceReceiver::class.java).apply {            action = AutomationGeofenceReceiver.ACTION_GEOFENCE_TRIGGERED        }        val pendingIntent = PendingIntent.getBroadcast(            context,            GEOFENCE_PI_BASE + (rule.id.hashCode() and 0xFFF),            intent,            pendingIntentFlags(),        )        try {            geofencingClient.addGeofences(request, pendingIntent)                .addOnSuccessListener {                    activeGeofenceIds.add(rule.id)                    Timber.tag(TAG).i(                        "Geofence added for '%s' (id=%s, lat=%.4f, lng=%.4f, r=%.0fm, action=%s)",                        rule.name, rule.id, trigger.latitude, trigger.longitude,                        trigger.radiusMeters, trigger.action,                    )                }                .addOnFailureListener { e ->                    Timber.tag(TAG).e(e, "Failed to add geofence for rule %s", rule.id)                }        } catch (se: SecurityException) {            Timber.tag(TAG).w(se, "Location permission missing — geofence not added for rule %s", rule.id)        }    }    /**     * Schedule a [AutomationTrigger.EventTrigger] via a dynamic BroadcastReceiver.     *     * Maps [EventType] to a system broadcast action and registers a receiver     * for it. When the receiver fires, it enqueues a OneTimeWorkRequest for     * [AutomationWorker].     */    private fun scheduleEventTrigger(        rule: AutomationRule,        trigger: AutomationTrigger.EventTrigger,    ) {        val action = eventTypeToAction(trigger.eventType) ?: run {            Timber.tag(TAG).w("No broadcast action for EventType %s — skipping rule %s", trigger.eventType, rule.id)            return        }        val receiver = object : BroadcastReceiver() {            override fun onReceive(ctx: Context?, intent: Intent?) {                Timber.tag(TAG).i("EventTrigger fired: %s (rule=%s)", trigger.eventType, rule.id)                enqueueOneShotFire(rule.id, AutomationWorker.TRIGGER_KIND_EVENT)            }        }        val filter = IntentFilter(action)        // Exported flag — required on Android 14+ for receivers registered        // for system broadcasts. We pass RECEIVER_NOT_EXPORTED since we only        // listen for system-internal broadcasts (which are still delivered        // to not-exported receivers).        registerReceiverCompat(receiver, filter)        activeReceivers[rule.id] = receiver        Timber.tag(TAG).i(            "Registered EventTrigger receiver for '%s' (id=%s, action=%s, eventType=%s)",            rule.name, rule.id, action, trigger.eventType,        )    }    /**     * Schedule a [AutomationTrigger.StateTrigger] via a dynamic BroadcastReceiver.     *     * Maps [StateType] to a system broadcast action and registers a receiver.     * For BATTERY_LEVEL, the receiver reads the battery level from the intent     * extras and only fires the worker if the level is at or below [value].     */    private fun scheduleStateTrigger(        rule: AutomationRule,        trigger: AutomationTrigger.StateTrigger,    ) {        val action = stateTypeToAction(trigger.stateType) ?: run {            Timber.tag(TAG).w("No broadcast action for StateType %s — skipping rule %s", trigger.stateType, rule.id)            return        }        val receiver = object : BroadcastReceiver() {            override fun onReceive(ctx: Context?, intent: Intent?) {                if (!stateTriggerMatches(trigger, intent)) return                Timber.tag(TAG).i("StateTrigger fired: %s=%s (rule=%s)", trigger.stateType, trigger.value, rule.id)                enqueueOneShotFire(rule.id, AutomationWorker.TRIGGER_KIND_STATE)            }        }        val filter = IntentFilter(action)        registerReceiverCompat(receiver, filter)        activeReceivers[rule.id] = receiver        Timber.tag(TAG).i(            "Registered StateTrigger receiver for '%s' (id=%s, action=%s, stateType=%s, value=%s)",            rule.name, rule.id, action, trigger.stateType, trigger.value,        )    }    /**     * Schedule a [AutomationTrigger.CompoundTrigger] — schedules each child     * trigger individually. When any child fires, the worker calls     * [AutomationEngine.fireRule] with `sourceTrigger`, and the engine     * evaluates the operator condition.     */    private fun scheduleCompoundTrigger(        rule: AutomationRule,        trigger: AutomationTrigger.CompoundTrigger,    ) {        Timber.tag(TAG).i(            "Scheduling CompoundTrigger for '%s' (id=%s, op=%s, children=%d)",            rule.name, rule.id, trigger.operator, trigger.triggers.size,        )        // Build a child-rule view for each child + schedule it.        // We use the parent rule ID as the WorkManager unique-work key —        // each child's work carries the parent's ruleId so the worker can        // call fireRule(parentId, sourceTrigger).        for (child in trigger.triggers) {            val childRule = rule.copy(                trigger = child,                // Don't re-fire the action on child fire — the parent engine                // evaluates the compound condition. We mark the child as a                // "compound child" by setting a special action that's a no-op;                // the worker checks for this via the TRIGGER_KIND_COMPOUND_CHILD                // input data flag.            )            // Schedule each child directly via the per-type scheduler.            when (child) {                is AutomationTrigger.TimeTrigger -> scheduleTimeTriggerForCompound(rule, child)                is AutomationTrigger.LocationTrigger -> scheduleLocationTrigger(rule, child)                is AutomationTrigger.EventTrigger -> scheduleEventTrigger(rule, child)                is AutomationTrigger.StateTrigger -> scheduleStateTrigger(rule, child)                is AutomationTrigger.CompoundTrigger -> {                    Timber.tag(TAG).w("Nested compound triggers not supported — skipping child of rule %s", rule.id)                }            }        }    }    /**     * Schedule a time-trigger child of a compound trigger. The worker, when     * fired, will call `AutomationEngine.fireRule(parentId, sourceTrigger)`     * instead of `fireRule(parentId)`.     */    private fun scheduleTimeTriggerForCompound(        parent: AutomationRule,        trigger: AutomationTrigger.TimeTrigger,    ) {        val delayMs = AutomationNlParser.nextFireDelayMs(trigger)        val request: OneTimeWorkRequest = OneTimeWorkRequestBuilder<AutomationWorker>()            .setInitialDelay(delayMs, TimeUnit.MILLISECONDS)            .setBackoffCriteria(BackoffPolicy.LINEAR, 60_000L, TimeUnit.MILLISECONDS)            .addTag(AUTOMATION_WORK_TAG)            .addTag(parent.id)            .setInputData(                workDataOf(                    AutomationWorker.KEY_RULE_ID to parent.id,                    AutomationWorker.KEY_TRIGGER_KIND to AutomationWorker.TRIGGER_KIND_COMPOUND_CHILD,                ),            )            .build()        // Use a unique work name per fire-cycle so the next day's schedule        // (registered after today's fire) doesn't collide.        workManager.enqueueUniqueWork(            "$FIRE_WORK_PREFIX${parent.id}_${System.currentTimeMillis()}",            ExistingWorkPolicy.REPLACE,            request,        )    }    // ═══════════════════════════════════════════════════════════════════════════    // Helpers    // ═══════════════════════════════════════════════════════════════════════════    /**     * Enqueue a one-shot [AutomationWorker] for the given [ruleId]. Used by     * [AutomationEventReceiver], [AutomationGeofenceReceiver], and any other     * trigger that fires outside of WorkManager's own schedule.     */    fun enqueueOneShotFire(ruleId: String, triggerKind: String) {        val request: OneTimeWorkRequest = OneTimeWorkRequestBuilder<AutomationWorker>()            .setBackoffCriteria(BackoffPolicy.LINEAR, 60_000L, TimeUnit.MILLISECONDS)            .addTag(AUTOMATION_WORK_TAG)            .addTag(ruleId)            .setInputData(                workDataOf(                    AutomationWorker.KEY_RULE_ID to ruleId,                    AutomationWorker.KEY_TRIGGER_KIND to triggerKind,                ),            )            .build()        workManager.enqueueUniqueWork(            "$FIRE_WORK_PREFIX${ruleId}_${System.currentTimeMillis()}",            ExistingWorkPolicy.REPLACE,            request,        )    }    /**     * Map [EventType] to a system broadcast action string.     *     * Returns `null` for events that can't be received via a simple     * BroadcastReceiver (e.g., NOTIFICATION_RECEIVED needs a     * NotificationListenerService, APP_LAUNCHED needs UsageStatsManager).     */    private fun eventTypeToAction(eventType: EventType): String? = when (eventType) {        EventType.CALL_INCOMING,        EventType.CALL_ANSWERED,        EventType.CALL_ENDED -> "android.intent.action.PHONE_STATE"        EventType.SMS_RECEIVED -> "android.provider.Telephony.SMS_RECEIVED"        EventType.APP_LAUNCHED -> null  // needs UsageStatsManager        EventType.NOTIFICATION_RECEIVED -> null  // needs NotificationListenerService        EventType.SCREEN_ON -> Intent.ACTION_SCREEN_ON        EventType.SCREEN_OFF -> Intent.ACTION_SCREEN_OFF        EventType.BOOT_COMPLETED -> Intent.ACTION_BOOT_COMPLETED        EventType.USER_PRESENT -> Intent.ACTION_USER_PRESENT    }    /**     * Map [StateType] to a system broadcast action string.     */    private fun stateTypeToAction(stateType: StateType): String = when (stateType) {        StateType.CHARGING -> Intent.ACTION_POWER_CONNECTED        StateType.POWER_DISCONNECTED -> Intent.ACTION_POWER_DISCONNECTED        StateType.BATTERY_LEVEL -> Intent.ACTION_BATTERY_CHANGED        StateType.WIFI_CONNECTED -> "android.net.wifi.STATE_CHANGE"        StateType.BLUETOOTH_CONNECTED -> "android.bluetooth.device.action.ACL_CONNECTED"        StateType.HEADPHONES_CONNECTED -> Intent.ACTION_HEADSET_PLUG        StateType.NETWORK_AVAILABLE -> "android.net.conn.CONNECTIVITY_CHANGE"    }    /**     * Check whether the broadcast intent's state matches the trigger's value.     *     * For [StateType.BATTERY_LEVEL], reads `BatteryManager.EXTRA_LEVEL` and     * `EXTRA_SCALE` and fires only if level <= trigger value.     *     * For all other state types, returns `true` (any broadcast = state matched).     */    private fun stateTriggerMatches(        trigger: AutomationTrigger.StateTrigger,        intent: Intent?,    ): Boolean {        if (intent == null) return false        return when (trigger.stateType) {            StateType.BATTERY_LEVEL -> {                val level = intent.getIntExtra(                    "level", -1,                )                val scale = intent.getIntExtra(                    "scale", 100,                )                val pct = if (scale > 0) (level * 100) / scale else -1                val threshold = trigger.value.toIntOrNull() ?: return false                pct in 0..threshold            }            else -> true        }    }    /**     * Register a BroadcastReceiver with the appropriate flags for the     * device's Android version.     *     * On Android 14+ (API 34+), `RECEIVER_NOT_EXPORTED` is required for     * non-system-protected broadcasts. For system-protected broadcasts     * (like BOOT_COMPLETED, SCREEN_ON), the flag is ignored.     */    private fun registerReceiverCompat(receiver: BroadcastReceiver, filter: IntentFilter) {        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {            context.registerReceiver(receiver, filter, Context.RECEIVER_NOT_EXPORTED)        } else {            @Suppress("UnspecifiedRegisterReceiverFlag")            context.registerReceiver(receiver, filter)        }    }    /**     * Compute PendingIntent flags with FLAG_IMMUTABLE on API 23+ (mandatory     * on API 31+).     */    private fun pendingIntentFlags(): Int {        return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE        } else {            PendingIntent.FLAG_UPDATE_CURRENT        }    }}